import { LanguageModelV3 } from '@ai-sdk/provider';

/**
 * Supported language model type.
 */
type LanguageModel = LanguageModelV3;
/**
 * Circuit breaker state for gateway URL health tracking.
 */
type CircuitState = 'closed' | 'open' | 'half-open';
/**
 * Makers Models settings.
 */
interface AiGatewaySettings {
    /**
     * API key created from the EdgeOne Makers console.
     * Priority: constructor argument > environment variable MAKERS_MODELS_KEY.
     */
    apiKey?: string;
}
/**
 * Makers Models provider function type.
 * Accepts either a single model identifier or an array of model identifiers (fallback mode).
 */
interface AiGateway {
    (modelId: string): LanguageModel;
    (modelIds: string[]): LanguageModel;
}
/**
 * Parsed model identifier.
 */
interface ParsedModelId {
    /** Provider name (e.g. "openai", "anthropic", "@makers"). */
    provider: string;
    /** Model name (e.g. "gpt-4", "claude-sonnet-4-5", "deepseek-v4-flash"). */
    model: string;
    /** Whether this is a @makers built-in model. */
    isMakers: boolean;
}

/**
 * Base class for custom errors.
 */
declare class AiGatewayError extends Error {
    constructor(message: string);
}
/**
 * Thrown when the model identifier format is invalid.
 */
declare class AiGatewayInvalidModelError extends AiGatewayError {
    readonly modelId: string;
    readonly reason: string;
    constructor(modelId: string, reason: string);
}
/**
 * Thrown when the API key is missing.
 */
declare class AiGatewayAuthError extends AiGatewayError {
    constructor();
}
/**
 * Thrown when the gateway configuration is invalid.
 */
declare class AiGatewayConfigError extends AiGatewayError {
}

/**
 * Create a Makers Models provider instance.
 *
 * @param settings - Makers Models settings.
 * @returns A Makers Models provider function that accepts a single model identifier or an array of identifiers (fallback mode).
 *
 * @example
 * ```typescript
 * // Single model
 * const aigateway = createAiGateway({ apiKey: 'sk-xxx' });
 * const model = aigateway("openai/gpt-4");
 * await generateText({ model, prompt: "Hello" });
 *
 * // @makers built-in free model
 * const model = aigateway("@makers/deepseek-v4-flash");
 * await generateText({ model, prompt: "Hello" });
 *
 * // Fallback mode (automatic failover across multiple models)
 * const model = aigateway([
 *   "anthropic/claude-sonnet-4-5",
 *   "@makers/deepseek-v4-flash"
 * ]);
 * await generateText({ model, prompt: "Hello" });
 * ```
 */
declare function createAiGateway(settings?: AiGatewaySettings): AiGateway;

export { AiGatewayAuthError, AiGatewayConfigError, AiGatewayError, AiGatewayInvalidModelError, createAiGateway, createAiGateway as default };
export type { AiGateway, AiGatewaySettings, CircuitState, LanguageModel, ParsedModelId };
